SELECT c.conversation_id, c.item_id, i.title AS item_title, i.cover AS item_cover, i.price AS item_price, i.status AS item_status, CASE WHEN c.buyer_id = #{currentUserId} THEN c.seller_id ELSE c.buyer_id END AS peer_id, CASE WHEN c.buyer_id = #{currentUserId} THEN su.nickname ELSE bu.nickname END AS peer_nickname, CASE WHEN c.buyer_id = #{currentUserId} THEN su.avatar ELSE bu.avatar END AS peer_avatar, CASE WHEN c.buyer_id = #{currentUserId} THEN su.campus ELSE bu.campus END AS peer_campus, c.last_message, c.last_time, CASE WHEN c.buyer_id = #{currentUserId} THEN c.buyer_unread ELSE c.seller_unread END AS unread FROM bobo_conversation c LEFT JOIN bobo_item i ON i.item_id = c.item_id LEFT JOIN bobo_user bu ON bu.user_id = c.buyer_id LEFT JOIN bobo_user su ON su.user_id = c.seller_id
c.del_flag = 0 AND (c.buyer_id = #{currentUserId} OR c.seller_id = #{currentUserId})
AND c.buyer_id = #{currentUserId}
AND c.seller_id = #{currentUserId}
ORDER BY c.last_time DESC, c.conversation_id DESC
